'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const fmt=(n,d=4)=>Number(n.toFixed(d)).toLocaleString('en-IN',{maximumFractionDigits:d});
const pct=p=>p>0&&p<.00001?(p*100).toExponential(4)+'%':p<1&&p>.999995?'≈100%':fmt(p*100,3)+'%';
const choose=(n,k)=>{if(k<0||k>n)return 0;let v=1;for(let i=1;i<=Math.min(k,n-k);i++)v=v*(n-i+1)/i;return Math.round(v)};
const binom=(n,p,k)=>choose(n,k)*p**k*(1-p)**(n-k);
const coins=n=>Array.from({length:2**n},(_,i)=>Array.from({length:n},(_,j)=>i&(1<<(n-j-1))?'T':'H').join(''));
const dice=()=>Array.from({length:36},(_,i)=>[Math.floor(i/6)+1,i%6+1]);
const phi=x=>Math.exp(-x*x/2)/Math.sqrt(2*Math.PI);
function Phi(x){if(x===0)return .5;const a=Math.abs(x),t=1/(1+.2316419*a);const tail=phi(a)*t*(.319381530+t*(-.356563782+t*(1.781477937+t*(-1.821255978+t*1.330274429))));return x>0?1-tail:tail;}
function normalSample(){let u=0,v=0;while(!u)u=Math.random();while(!v)v=Math.random();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v)}
const birthdayNoMatch=n=>{if(n>365)return 0;let p=1;for(let i=0;i<n;i++)p*=1-i/365;return p};
const birthday=n=>{if(n>365)return 1;return Math.min(1-birthdayNoMatch(n),1-Number.EPSILON)};
const density=x=>x<0||x>5?0:x<=1.4?2*x/7:(5-x)/9;
const densityCDF=x=>x<=0?0:x>=5?1:x<=1.4?x*x/7:1-(5-x)**2/18;
let active=0,explored=new Set(),currentTools={};
function mark(){explored.add(lessons[active].id);renderNav()}
function renderNav(){const nav=$('#nav');nav.innerHTML=groups.map((g,i)=>`<div class="nav-group"><span>${String(i+1).padStart(2,'0')} / ${g}</span>${lessons.map((l,j)=>l.group===i?`<button class="nav-item ${j===active?'active':''}" data-go="${j}" ${j===active?'aria-current="step"':''}><span class="nav-number">${explored.has(l.id)?'✓':String(j+1).padStart(2,'0')}</span>${l.title}</button>`:'').join('')}</div>`).join('');$$('[data-go]',nav).forEach(b=>b.onclick=()=>navigate(+b.dataset.go));$('#mobile-nav').innerHTML=groups.map((g,i)=>`<optgroup label="${g}">${lessons.map((l,j)=>l.group===i?`<option value="${j}" ${j===active?'selected':''}>${j+1}. ${l.title}</option>`:'').join('')}</optgroup>`).join('');$('#mobile-nav').onchange=e=>navigate(+e.target.value);$('#progress').value=explored.size;$('#progress-label').textContent=`${explored.size} of ${lessons.length} explored`;}
function navigate(i,scroll=true){active=clamp(i,0,lessons.length-1);const l=lessons[active];currentTools={};renderNav();$('#lesson').innerHTML=`<div class="lesson-top"><span class="eyebrow">${String(l.group+1).padStart(2,'0')} / ${groups[l.group]}</span><span class="lesson-count">EXPERIMENT ${active+1} OF ${lessons.length}</span></div><h1>${l.title}</h1><p class="lede">${l.desc}</p><div class="lesson-grid"><section class="explanation"><span class="step">01 &nbsp; THE PROBLEM</span><div id="problem"></div><div class="definition"><b>The foundation</b><p>${l.concept}</p></div><details class="notation"><summary>A small notation guide</summary><p><b>P(A)</b>: the probability of event A.<br><b>∪</b>: OR, including both.<br><b>∩</b>: AND, the overlap.<br><b>Aᶜ</b>: NOT A.<br><b>|</b>: GIVEN what follows it.<br><b>X</b>: a random variable.<br><b>∼</b>: “follows this distribution”.</p></details></section><section class="lab"><div class="lab-heading"><span class="step">02 &nbsp; TRY IT YOURSELF</span><span class="live-label" id="model-label">Explore the model</span></div><div id="activity"></div></section></div><div class="takeaway"><span>THE IDEA TO KEEP</span><p>${l.take}</p></div><section id="extras"></section><footer class="lesson-footer"><button class="secondary" id="prev" ${active===0?'disabled':''}>← Previous idea</button><span>${active+1} / ${lessons.length}</span><button class="primary" id="next">${active===lessons.length-1?'Back to the beginning':'Next idea →'}</button></footer>`;
$('#prev').onclick=()=>navigate(active-1);$('#next').onclick=()=>navigate(active===lessons.length-1?0:active+1);widgets[l.type](l);addExtras(l);history.replaceState(null,'','#'+l.id);if(scroll){window.scrollTo({top:0,behavior:'instant'});$('#lesson').focus({preventScroll:true})}}
function problem(title,body){$('#problem').innerHTML=`<h2>${title}</h2><p>${body}</p>`}
function selector(target,label,options,fn,value){const id='select-'+Math.random().toString(36).slice(2);target.insertAdjacentHTML('beforeend',`<label class="control-label" for="${id}">${label}</label><select id="${id}">${options.map((o,i)=>`<option value="${i}">${o}</option>`).join('')}</select>`);const el=$('#'+id);el.value=value??0;el.onchange=()=>fn(+el.value);return el}
function slider(target,label,min,max,step,value,fn){const id='range-'+Math.random().toString(36).slice(2);target.insertAdjacentHTML('beforeend',`<div class="slider-row"><label for="${id}">${label}</label><output for="${id}">${fmt(value)}</output><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></div>`);const el=$('#'+id);el.oninput=()=>{el.previousElementSibling.textContent=fmt(+el.value);fn(+el.value)};return el}
function button(target,label,fn,cls='secondary'){const b=document.createElement('button');b.className=cls;b.textContent=label;b.onclick=fn;target.append(b);return b}
function question(target,prompt,expected,solution,unit='%',tolerance=.11){const box=document.createElement('form');box.className='answer-box';box.noValidate=true;box.innerHTML=`<label>${prompt}<span class="answer-input"><input type="number" step="any" required inputmode="decimal" aria-label="${prompt}"><span>${unit}</span></span></label><div class="button-row"><button class="primary" type="submit">Check my answer</button><button class="text-button" type="button">Walk me through it</button></div><div class="answer-feedback" aria-live="polite"></div><div class="solution" hidden></div>`;target.append(box);const reveal=()=>{const s=$('.solution',box);s.innerHTML=`<span class="step">03 &nbsp; CONNECT THE IDEA</span><div>${typeof solution==='function'?solution():solution}</div>`;s.hidden=false;mark()};box.onsubmit=e=>{e.preventDefault();const raw=$('input',box).value;const actual=typeof expected==='function'?expected():expected;const tol=unit==='%'&&actual>0&&actual<.1?Math.min(tolerance,actual*.01):unit==='%'&&actual<100&&actual>99.9?Math.min(tolerance,(100-actual)*.01):tolerance;const good=raw.trim()!==''&&Number.isFinite(+raw)&&Math.abs(+raw-actual)<=tol;$('.answer-feedback',box).textContent=good?'Yes — that matches the model.':raw===''?'Enter a number, or use the walkthrough.':'A useful guess. Check which outcomes belong in the denominator, then compare with the walkthrough.';$('.answer-feedback',box).className='answer-feedback '+(good?'correct':'');if(good)reveal()};$('.text-button',box).onclick=reveal;return {reveal,box}}
function choiceQuestion(target,prompt,options,answer,explain){const wrap=document.createElement('div');wrap.className='choice-question';wrap.innerHTML=`<p><b>${prompt}</b></p><div class="button-row"></div><div aria-live="polite" class="choice-feedback"></div>`;target.append(wrap);options.forEach((o,i)=>button($('.button-row',wrap),o,()=>{$('.choice-feedback',wrap).innerHTML=`<p class="${i===answer?'correct':''}">${i===answer?'Exactly. ':'Try that idea against the model. '}${explain}</p>`;if(i===answer)mark()}));}
function miniStats(target,items){target.innerHTML=`<div class="stats">${items.map(([a,b])=>`<div><span>${a}</span><strong>${b}</strong></div>`).join('')}</div>`}
function bars(values,labels,selected=null,observed=null){const max=Math.max(...values,...(observed||[]),.01);return `<div class="bar-chart" role="img" aria-label="Probability bars: ${values.map((v,i)=>`${labels[i]}: ${pct(v)}`).join('; ')}">${values.map((v,i)=>`<div class="bar-col"><span class="bar-value">${values.length<=6?pct(v):''}</span><div class="bar-track"><div class="bar ${selected===null||selected===i?'highlight':''}" style="height:${100*v/max}%"></div>${observed?`<div class="observed-bar" style="height:${100*observed[i]/max}%"></div>`:''}</div><span>${values.length<=15||i%Math.ceil(values.length/6)===0||i===values.length-1?labels[i]:''}</span></div>`).join('')}</div>`}
function plot(f,{min=0,max=5,shadeMin=min,shadeMax=max,height=null,label='Probability density',cdf=false,overlay=null}={}){const W=650,H=255,L=50,R=22,T=20,B=42;const samples=240,ys=Array.from({length:samples+1},(_,i)=>f(min+(max-min)*i/samples));let ymax=height??Math.max(...ys.filter(Number.isFinite),.01)*1.1;if(cdf)ymax=1.08;const sx=x=>L+(x-min)/(max-min)*(W-L-R),sy=y=>H-B-clamp(y/ymax,0,1)*(H-T-B);const line=ys.map((y,i)=>`${i?'L':'M'}${sx(min+(max-min)*i/samples).toFixed(2)},${sy(y).toFixed(2)}`).join(' ');let a=clamp(shadeMin,min,max),b=clamp(shadeMax,min,max),fill='';if(b>a){fill=`M${sx(a)},${sy(0)} `+Array.from({length:121},(_,i)=>{let x=a+(b-a)*i/120;return `L${sx(x)},${sy(f(x))}`}).join(' ')+` L${sx(b)},${sy(0)} Z`};return `<svg viewBox="0 0 ${W} ${H}" class="plot" role="img" aria-label="${label}; horizontal range ${fmt(min)} to ${fmt(max)}"><title>${label}</title>${[0,.5,1].map(t=>`<line x1="${L}" y1="${sy(t*ymax)}" x2="${W-R}" y2="${sy(t*ymax)}" stroke="#e4ebef"/><text x="${L-9}" y="${sy(t*ymax)+5}" text-anchor="end">${fmt(t*ymax,2)}</text>`).join('')}<path d="${fill}" fill="#c3e8dc"/><path d="${line}" fill="none" stroke="#007f73" stroke-width="3"/>${overlay?`<path d="${Array.from({length:241},(_,i)=>{let x=min+(max-min)*i/240;return `${i?'L':'M'}${sx(x)},${sy(overlay(x))}`}).join(' ')}" fill="none" stroke="#c48a0e" stroke-width="2.5" stroke-dasharray="6 4"/>`:''}<line x1="${L}" y1="${H-B}" x2="${W-R}" y2="${H-B}" stroke="#819aa6"/>${Array.from({length:6},(_,i)=>{let x=min+(max-min)*i/5;return `<text x="${sx(x)}" y="${H-15}" text-anchor="middle">${fmt(x,2)}</text>`}).join('')}</svg>`}
const outcomeModes={
chance:()=>[{name:'A class of ten',title:'Who will be picked?',body:'The single-club class has 10 students: 3 play cricket, 4 play badminton and 3 play neither. Choose one student at random. What is the chance they play cricket?',items:Array.from({length:10},(_,i)=>({label:String(i+1).padStart(2,'0'),sub:i<3?'Cricket':i<7?'Badminton':'Neither',a:i<3})),why:'Every student is equally likely. Three of the ten are cricket players, so P(cricket) = 3/10 = 0.3 = 30%.'}],
coins:()=>[1,2,3].map(n=>({name:`${n} fair ${n===1?'toss':'tosses'} · all heads`,title:`${n===1?'Heads on one toss':`All heads in ${n} tosses`}`,body:`Toss a fair coin ${n} ${n===1?'time':'times independently'}. Select every sequence with ${n===1?'a head':'all heads'}. H = heads; T = tails. Each position records a particular toss.`,items:coins(n).map(s=>({label:s,a:!s.includes('T')})),why:`There are 2${n===1?'':`<sup>${n}</sup>`} = ${2**n} equally likely sequences, and only ${'H'.repeat(n)} is all heads. P(all heads) = 1/${2**n} = ${pct(1/2**n)}.`})),
dice:()=>[{name:'One die · face 4',title:'One face out of six',body:'Roll one fair six-sided die. Select the outcome that is 4.',items:Array.from({length:6},(_,i)=>({label:i+1,a:i===3})),why:'One favourable outcome out of six gives 1/6 ≈ 16.667%.'},{name:'One die · face 6',title:'Will you roll a six?',body:'Roll one fair six-sided die. Select the outcome that is 6.',items:Array.from({length:6},(_,i)=>({label:i+1,a:i===5})),why:'P(6) = 1/6. That is an exact model probability; the observed share of sixes varies.'},{name:'Two dice · both 6',title:'Two sixes together',body:'Roll two fair independent dice. Rows show die 1 and columns show die 2. Select every pair in which both dice are 6.',grid:true,items:dice().map(([a,b])=>({label:`${a}, ${b}`,a:a===6&&b===6})),why:'There are 6 × 6 = 36 equally likely ordered pairs. Only (6,6) succeeds, so P(both 6) = 1/36 ≈ 2.778%.'}],
complement:()=>[{name:'Class · not cricket',title:'Count those outside the event',body:'Return to the same single-club class of 10: 3 cricket, 4 badminton, 3 neither. Select every student who does not play cricket.',items:Array.from({length:10},(_,i)=>({label:i+1,sub:i<3?'Cricket':i<7?'Badminton':'Neither',a:i>=3})),why:'7 students do not play cricket. P(not cricket) = 1 − 3/10 = 7/10 = 70%.'},{name:'Three tosses · not all heads',title:'Does “not all” mean “none”?',body:'Toss three fair coins independently. Select all sequences that are NOT HHH. At least one tail is enough.',items:coins(3).map(s=>({label:s,a:s!=='HHH'})),why:'Only HHH is excluded. P(not all heads) = 1 − 1/8 = 7/8 = 87.5%. TTT is just one of these seven sequences.'},{name:'Three tosses · no heads',title:'A different event: no heads',body:'Keep the same three fair tosses. Now select sequences with no heads at all. Compare this with “not all heads”.',items:coins(3).map(s=>({label:s,a:s==='TTT'})),why:'No heads means TTT only: 1/8 = 12.5%. Its complement is “at least one head”, not “all heads”.'},{name:'One die · anything except 6',title:'All the other faces',body:'Roll one fair die and select every result other than 6.',items:Array.from({length:6},(_,i)=>({label:i+1,a:i!==5})),why:'P(not 6) = 1 − 1/6 = 5/6 ≈ 83.333%.'}],
disjoint:()=>[{name:'Single-club class · either sport',title:'One club at most',body:'In the single-club class, 3 students play cricket, 4 play badminton and 3 play neither. No student plays both. Select everyone who plays either sport.',items:Array.from({length:10},(_,i)=>({label:i+1,sub:i<3?'Cricket':i<7?'Badminton':'Neither',a:i<3,b:i>=3&&i<7})),union:true,why:'No overlap: 3 + 4 = 7 students. P(cricket or badminton) = 3/10 + 4/10 = 7/10 = 70%.'},{name:'One die · 2 or 3',title:'Two different faces',body:'Roll one fair die. Select 2 or 3. A single roll cannot be both.',items:Array.from({length:6},(_,i)=>({label:i+1,a:i===1,b:i===2})),union:true,why:'P(2 or 3) = 1/6 + 1/6 = 2/6 = 1/3.'},{name:'One die · even or 5',title:'An even number or five',body:'Roll one fair die. A is an even result (2,4,6); B is a result of 5. Select A or B.',items:Array.from({length:6},(_,i)=>({label:i+1,a:(i+1)%2===0,b:i===4})),union:true,why:'The sets {2,4,6} and {5} are disjoint. P(even or 5) = 3/6 + 1/6 = 4/6 = 2/3.'},{name:'Two dice · sum 7 or sum 10',title:'Two different sums',body:'Roll two fair independent dice. A is sum 7; B is sum 10. Select every pair satisfying either condition.',items:dice().map(([a,b])=>({label:`${a}, ${b}`,a:a+b===7,b:a+b===10})),grid:true,union:true,why:'Sum 7 has 6 pairs and sum 10 has 3. The sum cannot be both, so the union has 9/36 = 1/4 = 25%.'},{name:'Two dice · difference 2 or 1',title:'How far apart are the faces?',body:'Use the absolute difference: larger face minus smaller face. A is difference 2; B is difference 1. Select A or B.',items:dice().map(([a,b])=>({label:`${a}, ${b}`,a:Math.abs(a-b)===2,b:Math.abs(a-b)===1})),grid:true,union:true,why:'Difference 2 has 8 pairs; difference 1 has 10. They cannot overlap: (8+10)/36 = 18/36 = 50%.'}],
overlap:()=>[{name:'Multi-club class · either sport',title:'A different class allows two clubs',body:'This multi-club class also has 10 students: 6 play cricket, 5 play badminton, and 3 play both. That means 3 cricket only, 3 both, 2 badminton only and 2 neither. Select everyone in at least one club.',items:Array.from({length:10},(_,i)=>({label:i+1,sub:i<3?'Cricket':i<6?'Both':i<8?'Badminton':'Neither',a:i<6,b:i>=3&&i<8})),union:true,why:'Adding 6 and 5 counts the 3 dual-club students twice. Count them once: (6+5−3)/10 = 8/10 = 80%.'},{name:'Two dice · sum 7 or difference 1',title:'One pair can satisfy two rules',body:'Roll the same two fair independent dice. A is sum 7. B is absolute difference 1. Select all pairs in A or B, counting any overlap once.',grid:true,items:dice().map(([a,b])=>({label:`${a}, ${b}`,a:a+b===7,b:Math.abs(a-b)===1})),union:true,why:'A has 6 outcomes and B has 10. (3,4) and (4,3) satisfy both. P(A or B) = (6+10−2)/36 = 14/36 = 7/18 ≈ 38.889%.'}],
conditional:()=>[{name:'Two tosses · before any evidence',title:'Both heads, with no extra information',body:'Toss two fair independent coins. Select the sequence with both heads. All four sequences are possible.',items:coins(2).map(s=>({label:s,a:s==='HH'})),why:'Before evidence, HH is 1 of 4 possible sequences. P(HH) = 1/4.'},{name:'Two tosses · given first H',title:'You know the first toss was heads',body:'The first coin was H. Greyed-out sequences conflict with that evidence. Select the remaining sequence in which both coins are H.',items:coins(2).map(s=>({label:s,a:s==='HH',eligible:s[0]==='H'})),why:'The condition leaves HH and HT. Only HH succeeds, so P(HH | first H) = 1/2 = 50%.'},{name:'Two tosses · given first T',title:'You know the first toss was tails',body:'The first coin was T. Select remaining sequences with both heads. If none qualify, leave every tile unselected and check.',items:coins(2).map(s=>({label:s,a:s==='HH',eligible:s[0]==='T'})),why:'The remaining sequences are TH and TT. Neither is HH, so the conditional probability is 0/2 = 0.'},{name:'Two dice · sum 10, no evidence',title:'How often does the sum reach ten?',body:'Two fair independent dice are rolled. Select pairs summing to 10 before learning either result.',grid:true,items:dice().map(([a,b])=>({label:`${a}, ${b}`,a:a+b===10})),why:'Three ordered pairs sum to 10: (4,6),(5,5),(6,4). P(sum 10) = 3/36 = 1/12.'},{name:'Two dice · sum 10 given first 6',title:'Keep only the row with first die six',body:'You learn die 1 is 6. Select the remaining pair with sum 10. The denominator is now the six pairs compatible with this evidence.',grid:true,items:dice().map(([a,b])=>({label:`${a}, ${b}`,a:a+b===10,eligible:a===6})),why:'Only (6,4) succeeds within the six remaining pairs, so P(sum 10 | first 6) = 1/6. The general product gives P(first 6 AND sum 10) = (1/6)×(1/6) = 1/36.'},{name:'Two dice · sum 10 given first 1',title:'Could the total still be ten?',body:'You learn die 1 is 1. Select any remaining pair with sum 10. If none qualify, check an empty selection.',grid:true,items:dice().map(([a,b])=>({label:`${a}, ${b}`,a:a+b===10,eligible:a===1})),why:'The largest possible sum in this row is 1+6 = 7. There are 0 favourable outcomes out of 6, so P(sum 10 | first 1) = 0.'}]
};
function outcomes(l){const modes=outcomeModes[l.id]();const root=$('#activity');const modeSlot=document.createElement('div'),scene=document.createElement('div');root.append(modeSlot,scene);let m=0;selector(modeSlot,'Choose the experiment',modes.map(x=>x.name),i=>{m=i;draw()});function draw(){const s=modes[m],valid=s.items.filter(x=>x.eligible!==false),win=x=>x.eligible!==false&&(x.a||(s.union&&x.b)),count=s.items.filter(win).length;let selected=new Set(),hint=false;problem(s.title,s.body);$('#model-label').textContent=valid.length+' equally likely outcomes';scene.innerHTML=`<h2>Build the event</h2><p class="hint">Tap the outcomes that answer the question. ${s.grid?'Rows = die 1; columns = die 2.':''}</p>${s.union?'<div class="legend"><span><i class="key a"></i>A</span><span><i class="key b"></i>B</span><span><i class="key both"></i>Both</span></div>':''}<div class="outcome-grid ${s.grid?'dice-grid':''}" role="group" aria-label="Selectable outcomes">${s.items.map((x,i)=>`<button class="outcome" data-index="${i}" aria-pressed="false" ${x.eligible===false?'disabled':''}><b>${x.label}</b>${x.sub?`<small>${x.sub}</small>`:''}</button>`).join('')}</div><div class="selection-count" aria-live="polite">0 selected / ${valid.length} possible</div><div class="button-row"><button class="primary" id="check-selection">Check my selection</button><button class="text-button" id="show-selection">Show a guided solution</button><button class="text-button" id="reset-selection">Clear</button></div><div class="outcome-feedback" aria-live="polite"></div><div class="solution" hidden></div><div id="sim-slot"></div>`;
const paint=()=>{$$('[data-index]',scene).forEach(b=>{let i=+b.dataset.index,x=s.items[i];b.classList.toggle('selected',selected.has(i));b.setAttribute('aria-pressed',selected.has(i));b.classList.toggle('event-a',hint&&x.a);b.classList.toggle('event-b',hint&&!!x.b);b.classList.toggle('event-both',hint&&x.a&&!!x.b)});$('.selection-count',scene).textContent=`${selected.size} selected / ${valid.length} possible = ${pct(selected.size/valid.length)}`};
$$('[data-index]',scene).forEach(b=>b.onclick=()=>{let i=+b.dataset.index;selected.has(i)?selected.delete(i):selected.add(i);paint()});
const reveal=()=>{hint=true;paint();$('.solution',scene).hidden=false;$('.solution',scene).innerHTML=`<span class="step">03 &nbsp; CONNECT THE IDEA</span><p>${s.why}</p><div class="formula">${count} favourable ÷ ${valid.length} possible = ${pct(count/valid.length)}</div>${s.union?`<p>A: ${s.items.filter(x=>x.a).length} · B: ${s.items.filter(x=>x.b).length} · Both: ${s.items.filter(x=>x.a&&x.b).length}</p>`:''}`;mark()};
$('#check-selection').onclick=()=>{const ok=s.items.every((x,i)=>selected.has(i)===!!win(x));$('.outcome-feedback',scene).textContent=ok?'Exactly — every qualifying outcome is included once.':'Compare each tile with the exact wording. Include every match, and exclude outcomes that do not qualify.';if(ok)reveal()};$('#show-selection').onclick=()=>{selected=new Set(s.items.flatMap((x,i)=>win(x)?[i]:[]));reveal()};$('#reset-selection').onclick=()=>{selected.clear();hint=false;paint();$('.solution',scene).hidden=true;$('.outcome-feedback',scene).textContent=''};
if(l.id==='dice'){let runs=0,hits=0;const el=$('#sim-slot');el.innerHTML='<details class="simulation"><summary>Roll and compare with the model</summary><p>Each roll is drawn independently from the selected experiment.</p><div class="button-row"></div><div class="sim-stats" aria-live="polite"></div></details>';const update=()=>miniStats($('.sim-stats',el),[['Rolls',runs],['Observed',runs?pct(hits/runs):'—'],['Model',pct(count/valid.length)]]);[1,10,100,1000].forEach(n=>button($('.button-row',el),'Roll '+n,()=>{for(let i=0;i<n;i++){runs++;hits+=win(s.items[Math.floor(Math.random()*s.items.length)])?1:0}update();mark()}));button($('.button-row',el),'Reset',()=>{runs=hits=0;update()});update()}
}draw();}
function product(){problem('How unlikely is “every time”?','Choose independent fair coin tosses or die rolls. Predict the chance that every result is a head or every result is a six.');const root=$('#activity');let coin=true,n=5;const controls=document.createElement('div'),scene=document.createElement('div');root.append(controls,scene);selector(controls,'Trial type',['Fair coin · all heads','Fair die · all sixes'],i=>{coin=i===0;draw()});slider(controls,'Number of independent trials',1,10,1,n,v=>{n=v;draw()});function draw(){const p=coin?.5:1/6,res=p**n;scene.innerHTML=`<div class="factor-chain">${Array.from({length:n},(_,i)=>`<span>${coin?'½':'⅙'}</span>${i<n-1?'<b>×</b>':''}`).join('')}</div><p>Every factor is the chance of success on one trial. No trial changes the next trial’s chance.</p>`;question(scene,'What denominator belongs in 1 / denominator?',(coin?2:6)**n,`<p>P(all ${coin?'heads':'sixes'}) = (1/${coin?2:6})<sup>${n}</sup> = <b>1/${fmt((coin?2:6)**n,0)}</b> = ${pct(res)}.</p><p>${n===10&&!coin?'That is one favourable sequence among 6,04,66,176 equally likely sequences.':'The product rule agrees with counting the full sequences.'}</p>`,'',.01)}draw()}
function rooms(){const root=$('#activity');let mode=0;const configs=[{name:'Random split A · 50 players, rooms 50 / 50',sport:50,room:50},{name:'Random split B · 40 players, rooms 30 / 70',sport:40,room:30},{name:'Chosen rooms · cricket match versus film',sport:50,room:50,chosen:true}];const c=document.createElement('div'),s=document.createElement('div');root.append(c,s);selector(c,'Choose a clearly different setup',configs.map(x=>x.name),v=>{mode=v;draw()});function draw(){const x=configs[mode],expected=x.sport*x.room/100;problem('Who is in room one?',x.chosen?'There are 100 students: 50 cricket fans and 50 others. Room 1 shows a cricket match; room 2 shows a film. For this deliberately extreme illustration, assume all cricket fans choose room 1 and all others choose room 2. Each room holds 50.':`There are 100 students, ${x.sport} of whom play cricket. Assign exactly ${x.room} students uniformly at random to room 1 and the remaining ${100-x.room} to room 2. How many cricket players do you expect in room 1?`);let people=Array.from({length:100},(_,i)=>i<x.sport),attempts=0,total=0;const shuffle=()=>{for(let i=99;i>0;i--){let j=Math.floor(Math.random()*(i+1));[people[i],people[j]]=[people[j],people[i]]}};if(!x.chosen)shuffle();s.innerHTML='<div class="legend"><span><i class="key a"></i>Cricket</span><span><i class="key neutral"></i>Other</span></div><div class="room-grid"></div><div class="button-row"></div><div class="room-stats" aria-live="polite"></div><div class="room-answer"></div>';function show(){let hit=people.slice(0,x.room).filter(Boolean).length;$('.room-grid',s).innerHTML=[people.slice(0,x.room),people.slice(x.room)].map((arr,i)=>`<div class="room"><b>Room ${i+1} · ${arr.length} students</b><div class="dot-grid" role="img" aria-label="${arr.filter(Boolean).length} cricket players of ${arr.length}">${arr.map(v=>`<i class="dot ${v?'yes':''}"></i>`).join('')}</div><span>${arr.filter(Boolean).length} cricket / ${arr.length}</span></div>`).join('');miniStats($('.room-stats',s),[['Current room 1',hit],['Model expectation',x.chosen?50:expected],['Average over shuffles',attempts?fmt(total/attempts,2):'—']]);}if(!x.chosen){button($('.button-row',s),'Shuffle rooms',()=>{shuffle();attempts++;total+=people.slice(0,x.room).filter(Boolean).length;show();mark()});button($('.button-row',s),'Try 500 allocations',()=>{for(let i=0;i<500;i++){shuffle();attempts++;total+=people.slice(0,x.room).filter(Boolean).length}show();mark()});}show();question($('.room-answer',s),x.chosen?'Of room 1, what percentage are cricket fans?':'Expected number of cricket players in room 1?',x.chosen?100:expected,x.chosen?'<p>Under this stated choice rule, P(cricket | room 1) = 100%, compared with 50% overall. Knowing the room changes the probability, so the events are dependent.</p>':`<p>${x.sport}% of ${x.room} = ${expected} players <b>on average</b>. P(cricket AND room 1) = ${x.sport/100} × ${x.room/100} = ${pct(expected/100)}.</p><p>A single shuffle may differ. Randomly assigning rooms does not force exact proportional counts in every realised class.</p>`,x.chosen?'%':'students');}draw()}
function birthdayLab(){problem('Will any two friends match?','Start with 30 friends, excluding yourself. Is a shared birthday more likely than no shared birthday? Adjust the group size, make a prediction, and generate groups.');const r=$('#activity');let n=30,runs=0,hits=0;const c=document.createElement('div'),s=document.createElement('div');r.append(c,s);slider(c,'People in the group',1,366,1,n,v=>{n=v;runs=hits=0;draw()});const preset=document.createElement('div');preset.className='button-row';c.append(preset);[2,3,20,23,30,50,100,366].forEach(v=>button(preset,''+v,()=>{n=v;$('input',c).value=v;$('output',c).textContent=v;runs=hits=0;draw()}));function draw(){s.innerHTML='<div class="birthday-prediction"></div><div class="birthday-viz"></div><div class="button-row"></div><div class="birthday-stats" aria-live="polite"></div><details class="math-details"><summary>Why the complement is easier</summary><div class="birthday-solution"></div></details>';choiceQuestion($('.birthday-prediction',s),'Which is more likely in this group?',['At least one match','All different'],birthday(n)>.5?0:1,`At n=${n}, a match has probability ${pct(birthday(n))}.`);$('.birthday-viz',s).innerHTML=plot(x=>birthday(Math.round(x)),{min:1,max:100,shadeMin:1,shadeMax:Math.min(n,100),height:1.05,label:'Theoretical probability of any shared birthday by group size'})+'<div class="plot-caption">Horizontal: people · Vertical: probability of any match</div><div class="birthday-list"></div>';function update(){miniStats($('.birthday-stats',s),[['Exact model',pct(birthday(n))],['Groups simulated',runs],['Observed matches',runs?pct(hits/runs):'—']])}function sample(times){let last=[];for(let j=0;j<times;j++){last=Array.from({length:n},()=>Math.floor(Math.random()*365));runs++;hits+=new Set(last).size<n?1:0}const counts={};last.forEach(d=>counts[d]=(counts[d]||0)+1);$('.birthday-list',s).innerHTML=`<p>Latest group: ${n-new Set(last).size} repeated date entries. Matching dates are highlighted. ${n>60?'Showing the first 60 people.':''}</p><div class="date-chips">${last.slice(0,60).map((d,i)=>`<span class="${counts[d]>1?'match':''}" title="Person ${i+1}">${new Date(Date.UTC(2025,0,d+1)).toLocaleDateString('en-IN',{day:'numeric',month:'short',timeZone:'UTC'})}</span>`).join('')}</div>`;update();mark()}button($('.button-row',s),'Generate one group',()=>sample(1),'primary');button($('.button-row',s),'Simulate 1,000 groups',()=>sample(1000));button($('.button-row',s),'Reset runs',()=>{runs=hits=0;$('.birthday-list',s).innerHTML='';update()});$('.birthday-solution',s).innerHTML=`<p>The first person may have any birthday: 365/365. The second must avoid one occupied date: 364/365. Given the first two are different, the third has 363/365 available.</p><div class="formula">P(all different) = 365/365 × 364/365 × 363/365 × …</div><p>For ${n} people: all different = ${pct(birthdayNoMatch(n))}; at least one match = 1 − that = <b>${pct(birthday(n))}</b>.</p><p>There are n(n−1)/2 = ${fmt(n*(n-1)/2,0)} distinct pairs. At 23 people the match probability first exceeds 50%. At 366 people a match is certain. For 365 or fewer it is not mathematically certain, even when the displayed percentage is extremely close to 100%.</p>`;update()}draw()}
function shoes(){problem('Build the four groups','In our sports-shoes school, 40 of 100 students play cricket. Of those 40, 80% wear sports shoes. Of the 60 other students, 50% wear sports shoes. Work down the two branches.');const r=$('#activity');r.innerHTML=`<div class="tree-root">100 students</div><div class="tree"><div class="tree-branch"><div class="tree-node">Cricket <strong>40% → 40</strong></div><div class="tree-leaves"><div>Shoes <b>80% of 40</b><input type="number" min="0" max="40" aria-label="Cricket and shoes count"></div><div>No shoes <b>20% of 40</b><input type="number" min="0" max="40" aria-label="Cricket and no shoes count"></div></div></div><div class="tree-branch"><div class="tree-node other">Other students <strong>60% → 60</strong></div><div class="tree-leaves"><div>Shoes <b>50% of 60</b><input type="number" min="0" max="60" aria-label="Other students with shoes count"></div><div>No shoes <b>50% of 60</b><input type="number" min="0" max="60" aria-label="Other students without shoes count"></div></div></div></div><div class="button-row"></div><div class="tree-feedback" aria-live="polite"></div><div class="tree-solution" hidden></div>`;function reveal(){const el=$('.tree-solution',r);el.hidden=false;el.innerHTML=`<div class="formula">0.4 × 0.8 = 0.32 &nbsp; · &nbsp; 0.4 × 0.2 = 0.08<br>0.6 × 0.5 = 0.30 &nbsp; · &nbsp; 0.6 × 0.5 = 0.30</div><p>The four leaves are 32, 8, 30 and 30. They add to 100.</p><div class="tree-next"></div>`;selector($('.tree-next',el),'Now choose the question',['How many wear shoes?','Given shoes, how many play cricket?'],i=>follow(i));function follow(i){let slot=$('.followup',el);if(slot)slot.remove();slot=document.createElement('div');slot.className='followup';el.append(slot);question(slot,i?'Among shoe wearers, what percentage play cricket?':'What percentage of all students wear shoes?',i?100*32/62:62,i?'<p>Keep only the 32+30 = 62 shoe wearers. Of those, 32 play cricket. P(cricket | shoes) = 32/62 ≈ 51.613%. This reverses the original condition.</p>':'<p>Add the disjoint shoes paths: 32+30 = 62 students. P(shoes) = 0.4×0.8 + 0.6×0.5 = 0.62. This is the law of total probability.</p>')}follow(0);mark()}button($('.button-row',r),'Check the leaves',()=>{const vals=$$('.tree-leaves input',r).map(x=>x.value);const ok=vals.every((v,i)=>v!==''&&+v===[32,8,30,30][i]);$('.tree-feedback',r).textContent=ok?'Exactly. Each percentage applies inside its own branch.':'Multiply each branch size by its shoes or no-shoes rate.';if(ok)reveal()},'primary');button($('.button-row',r),'Show the tree solution',()=>{$$('.tree-leaves input',r).forEach((x,i)=>x.value=[32,8,30,30][i]);reveal()})}
function bayes(){problem('Out of positive tests, how many are truly affected?','Imagine testing all 10,00,000 people in this fictional population. There are 100 affected people and 9,99,900 unaffected people. Make an intuition guess, then restrict your attention to the positive results.');const r=$('#activity');r.innerHTML=`<div class="bayes-intuition"></div><div class="button-row" id="bayes-filter"></div><div class="table-wrap"><table><caption>Exact counts in the fictional test model</caption><thead><tr><th>Actual status</th><th>Positive test</th><th class="negative-col">Negative test</th><th class="negative-col">Total</th></tr></thead><tbody><tr><th>Affected</th><td class="true-pos">99</td><td class="negative-col">1</td><td class="negative-col">100</td></tr><tr><th>Unaffected</th><td class="false-pos">9,999</td><td class="negative-col">9,89,901</td><td class="negative-col">9,99,900</td></tr><tr><th>Total</th><td><b>10,098</b></td><td class="negative-col">9,89,902</td><td class="negative-col">10,00,000</td></tr></tbody></table></div><div class="bayes-answer"></div>`;choiceQuestion($('.bayes-intuition',r),'Before calculating, where would you put the answer?',['Below 1%','About 50%','About 99%'],0,'The positive group contains 99 affected people and 9,999 unaffected people.');let only=false;button($('#bayes-filter'),'Focus on positive tests',()=>{only=!only;$$('.negative-col',r).forEach(c=>c.classList.toggle('dimmed',only));$('#bayes-filter button').textContent=only?'Show the whole population':'Focus on positive tests';mark()});question($('.bayes-answer',r),'Probability affected, given positive?',100/102,`<p>Of the 10,098 positive results, 99 are from affected people.</p><div class="formula">99 / (99 + 9,999) = 1/102 ≈ 0.9804%</div><p>The <b>prior</b> is 0.01%. The <b>likelihood</b> of a positive result within the affected group is 99%. The <b>posterior</b>, affected given positive, is about 0.98%.</p><div class="formula">P(A | +) = [P(A)P(+ | A)] / [P(A)P(+ | A) + P(Aᶜ)P(+ | Aᶜ)]</div><p>Insert the rates: (0.0001×0.99) / (0.0001×0.99 + 0.9999×0.01). The denominator adds both disjoint ways to test positive.</p>`)}
function spam(){problem('Which group belongs in the denominator?','The same 100-message inbox has 20 spam and 80 regular messages. “Lottery” appears in 14 spam and 10 regular messages. Select evidence and see which messages remain relevant.');const r=$('#activity');let mode=0;const c=document.createElement('div'),s=document.createElement('div');r.append(c,s);selector(c,'What do you know?',['No evidence · all messages','Contains “lottery”','Does not contain “lottery”','Already known to be spam'],v=>{mode=v;draw()});function draw(){const totals=[100,24,76,20],fav=[20,14,6,14];s.innerHTML=`<div class="inbox-grid">${Array.from({length:100},(_,i)=>{const spam=i<20,lottery=spam?i<14:i<30,eligible=mode===0||mode===1&&lottery||mode===2&&!lottery||mode===3&&spam;return `<span class="message-chip ${spam?'spam-chip':''} ${eligible?'':'excluded'}" title="${spam?'Spam':'Regular'} · ${lottery?'lottery':'no lottery'}" aria-label="${spam?'Spam':'Regular'}, ${lottery?'lottery':'no lottery'}, ${eligible?'included':'excluded'}">${spam?'S':'R'}${lottery?'•':''}</span>`}).join('')}</div><div class="legend"><span>S = spam</span><span>R = regular</span><span>• = “lottery”</span><span>Faded = excluded</span></div><div class="table-wrap"><table><thead><tr><th></th><th>Lottery</th><th>No lottery</th><th>Total</th></tr></thead><tbody><tr><th>Spam</th><td>14</td><td>6</td><td>20</td></tr><tr><th>Regular</th><td>10</td><td>70</td><td>80</td></tr></tbody></table></div>`;question(s,mode===3?'Among spam, what percentage contains “lottery”?':'Among the included messages, what percentage is spam?',100*fav[mode]/totals[mode],`<p>Count within the selected group: ${fav[mode]} / ${totals[mode]} = <b>${pct(fav[mode]/totals[mode])}</b>.</p>${mode===1?'<div class="formula">P(spam | lottery) = (0.2×0.7) / (0.2×0.7 + 0.8×0.125)</div><p>Prior 20% → evidence “lottery” → posterior 58.333%. A keyword raises this probability without making it certain.</p>':mode===3?'<p>This is P(lottery | spam) = 70%, a different question from P(spam | lottery) ≈ 58.333%.</p>':mode===2?'<p>The absence of “lottery” lowers the spam probability from 20% to about 7.895%.</p>':'<p>This is the prior probability of spam before inspecting a keyword.</p>'}`)}draw()}
function naive(){problem('Two clues in the same inbox','“Lottery” appears in 14/20 spam and 10/80 regular messages. “Winning” appears in 15/20 spam and 8/80 regular messages. Choose the words present in a new message, then normalise the class scores.');const r=$('#activity');r.innerHTML='<div class="word-controls"><label><input type="checkbox" id="lottery" checked> lottery</label><label><input type="checkbox" id="winning" checked> winning</label></div><p class="hint">An unchecked clue is ignored; it does not mean that word is absent.</p><div id="naive-scene"></div>';function draw(){const a=$('#lottery').checked,b=$('#winning').checked,sp=.2*(a?.7:1)*(b?.75:1),reg=.8*(a?.125:1)*(b?.1:1);const s=$('#naive-scene');s.innerHTML=`<div class="score-lane"><span>Spam</span><div>0.2 ${a?'× 0.7':''} ${b?'× 0.75':''}</div><strong>${fmt(sp)}</strong></div><div class="score-lane regular"><span>Regular</span><div>0.8 ${a?'× 0.125':''} ${b?'× 0.1':''}</div><strong>${fmt(reg)}</strong></div><p class="assumption">${a&&b?'These are model scores, not observed joint counts. We assume “lottery” and “winning” are independent within spam, and also within regular messages.':'With one clue, the score calculation agrees with the observed one-word counts. With no clues, it returns the prior.'}</p>`;question(s,'What percentage of the total score belongs to spam?',100*sp/(sp+reg),`<div class="formula">Spam score ÷ (spam score + regular score)<br>${fmt(sp)} / (${fmt(sp)} + ${fmt(reg)}) = ${pct(sp/(sp+reg))}</div><p>Normalising makes the two class probabilities add to 100%. ${a&&b?'The inbox specifies individual word counts but no measured count for both words together, so 91.304% is the naïve-model estimate.':''}</p>`)}$('#lottery').onchange=$('#winning').onchange=draw;draw()}
function boxes(){problem('Keep your box or switch?','At a festival stall, exactly one of three closed boxes contains a prize, placed uniformly at random. Pick a box. The informed host opens an unchosen empty box. You may keep your choice or switch to the other closed box.');const r=$('#activity');let prize=0,pick=null,opened=null,finished=false,stayWins=0,switchWins=0,runs=0;function fresh(){prize=Math.floor(Math.random()*3);pick=opened=null;finished=false;draw()}function draw(){r.innerHTML=`<p class="box-status" aria-live="polite">${pick===null?'Choose a box.':finished?'Round complete. Try another round or compare strategies below.':'The host revealed an empty box. Keep your first choice or switch?'}</p><div class="prize-boxes">${[0,1,2].map(i=>`<button class="prize-box ${pick===i?'chosen':''} ${opened===i?'opened':''}" data-box="${i}" ${pick!==null?'disabled':''}><span>BOX ${i+1}</span><b>${finished?(i===prize?'PRIZE':'EMPTY'):i===opened?'EMPTY':'?'}</b><small>${pick===i?'Your choice':opened===i?'Host opened':'Closed'}</small></button>`).join('')}</div><div class="box-actions button-row"></div><div class="round-result" aria-live="polite"></div><div class="strategy-stats"></div><div class="simulation button-row"></div><details><summary>Why switching has probability 2/3</summary><p>Your first pick wins with chance 1/3. The two unchosen boxes together carry chance 2/3. The host’s guaranteed empty reveal leaves the other closed box with that 2/3 chance.</p><p>Equivalently: if your first pick was wrong, switching wins. The first pick is wrong in 2 of 3 equally likely prize placements. If the host opened a box without knowing the prize, these rules and the calculation would change.</p></details>`;$$('[data-box]',r).forEach(b=>b.onclick=()=>{pick=+b.dataset.box;const candidates=[0,1,2].filter(i=>i!==pick&&i!==prize);opened=candidates[Math.floor(Math.random()*candidates.length)];draw()});if(pick!==null&&!finished){button($('.box-actions',r),'Keep my box',()=>finish(false),'primary');button($('.box-actions',r),'Switch boxes',()=>finish(true),'primary')}button($('.box-actions',r),'New round',fresh);button($('.simulation',r),'Compare 1,000 prize placements',()=>{for(let i=0;i<1000;i++){let hit=Math.random()<1/3;stayWins+=hit?1:0;switchWins+=hit?0:1;runs++}update();mark()});button($('.simulation',r),'Reset comparison',()=>{stayWins=switchWins=runs=0;update()});update()}function update(){miniStats($('.strategy-stats',r),[['Compared trials',runs],['Always keep',runs?pct(stayWins/runs):'Model: 33.333%'],['Always switch',runs?pct(switchWins/runs):'Model: 66.667%']])}function finish(sw){let finalPick=sw?[0,1,2].find(i=>i!==pick&&i!==opened):pick;finished=true;draw();$('.round-result',r).innerHTML=`<p class="${finalPick===prize?'correct':''}">${sw?'You switched':'You kept'} to box ${finalPick+1}. ${finalPick===prize?'You found the prize!':'The prize was in box '+(prize+1)+'.'} One round can go either way; compare the long-run strategies.</p>`;mark()}fresh()}
function randomVariable(){const r=$('#activity');let mode=0;const c=document.createElement('div'),s=document.createElement('div');r.append(c,s);selector(c,'Choose a numerical rule',['One toss → number of heads','Ten tosses → number of heads','Ten dice → number of ones','Three unusual numerical values','A deterministic rule: square x'],v=>{mode=v;draw()});function draw(){s.innerHTML='';if(mode===4){problem('Known input, known answer','For the deterministic rule f(x) = x², knowing x fixes the answer. Compare this with a count whose value depends on a random experiment.');let x=2;slider(s,'Input x',-5,5,1,x,v=>{x=v;$('#fixed-result').textContent=`f(${x}) = ${x}² = ${x*x}`});s.insertAdjacentHTML('beforeend','<div class="formula" id="fixed-result">f(2) = 2² = 4</div>');question(s,'When x = 3, what is f(x)?',9,'<p>The rule gives 3² = 9. There is no randomness once x is fixed.</p>','');return}if(mode===3){problem('Must a discrete value be a whole number?','A deliberately invented random variable takes exactly three possible values: 1 with chance 50%, −7 with chance 20%, and 3.14159 with chance 30%. These values are separate, so the variable is discrete.');s.innerHTML=bars([.5,.2,.3],['1','−7','3.14159'])+'<div class="button-row"></div><div class="random-result" aria-live="polite"></div>';button($('.button-row',s),'Draw a value',()=>{let u=Math.random(),v=u<.5?1:u<.7?-7:3.14159;$('.random-result',s).innerHTML=`<div class="formula">X = ${v}</div>`;mark()},'primary');choiceQuestion(s,'Why is this variable discrete?',['It has only three possible values','Its values must be positive integers'],0,'Finite or countably many distinct possible values is what matters. Negative and decimal values are allowed.');return}const n=mode===0?1:10;problem('A rule turns a result into a number',mode===2?'Roll a fair die 10 times independently. Define X as the number of ones. The full outcome has ten faces; X keeps just the count of face 1.':`Toss a fair coin ${n} ${n===1?'time':'times independently'}. Define X as the number of heads. Each sequence is an outcome; X is the numerical summary.`);s.innerHTML='<div class="random-outcome"></div><div class="button-row"></div><div class="random-answer"></div>';function toss(){let values=Array.from({length:n},()=>mode===2?1+Math.floor(Math.random()*6):Math.random()<.5?'H':'T'),count=values.filter(v=>mode===2?v===1:v==='H').length;$('.random-outcome',s).innerHTML=`<div class="sequence">${values.map(v=>`<span class="${v==='H'||v===1?'success':''}">${v}</span>`).join('')}</div><div class="formula">X = ${count} ${mode===2?'ones':'heads'}</div><p>Possible X values: 0, 1, …, ${n}. ${n===1?'H maps to 1 and T maps to 0.':''}</p>`;mark()}button($('.button-row',s),'Run the experiment',toss,'primary');$('.random-outcome',s).innerHTML='<p>Run once to see an outcome and its numerical value.</p>';question($('.random-answer',s),`If ${mode===2?'three of the ten dice show 1':n===1?'the coin lands T':'the sequence is HHHHHHHHHT'}, what is X?`,mode===2?3:n===1?0:9,`<p>X is just the count: ${mode===2?3:n===1?0:9}. ${mode===1?'There are ten different sequences with nine heads, because the single tail can occupy any of ten positions. One specific sequence has probability 1/1024, but X=9 has probability 10/1024.':''}</p>`,'');}draw()}
function discrete(){const r=$('#activity');let n=3,k=2,runs=0,counts=[];const c=document.createElement('div'),s=document.createElement('div');r.append(c,s);selector(c,'Fair, independent coin tosses',['3 tosses','4 tosses','5 tosses','10 tosses','1 toss'],v=>{n=[3,4,5,10,1][v];k=Math.min(k,n);runs=0;counts=[];draw()});function draw(){problem('How much probability belongs to each count?',`Toss ${n} fair coins independently and let X be the number of heads. Every detailed sequence has probability 1/${2**n}, but many sequences can lead to the same X.`);s.innerHTML='<div class="count-choices button-row"></div><div class="discrete-plot"></div><div class="discrete-sequences"></div><div class="discrete-question"></div><details class="simulation"><summary>Repeat the experiment and compare</summary><p>One experiment means '+n+' tosses. A batch of 500 means '+fmt(n*500,0)+' individual tosses.</p><div class="button-row"></div><div class="sim-stats" aria-live="polite"></div></details>';Array.from({length:n+1},(_,i)=>button($('.count-choices',s),'X = '+i,()=>{k=i;refresh()}));function refresh(){const vals=Array.from({length:n+1},(_,i)=>binom(n,.5,i));$('.discrete-plot',s).innerHTML=bars(vals,vals.map((_,i)=>i),k,runs?counts.map(v=>v/runs):null)+'<div class="plot-caption">Teal = exact PMF · Gold = simulated share (when sampled)</div>';const seq=coins(n).filter(v=>v.split('H').length-1===k);$('.discrete-sequences',s).innerHTML=`<p>Sequences that give X = ${k}: ${seq.length}${seq.length>32?' (first 32 shown)':''}</p><div class="sequence-list">${seq.slice(0,32).map(v=>`<code>${v}</code>`).join('')}</div>`;$('.discrete-question',s).innerHTML='';question($('.discrete-question',s),`What is P(X = ${k}) as a percentage?`,100*vals[k],`<p>${choose(n,k)} sequences have ${k} heads, out of ${2**n} total sequences.</p><div class="formula">P(X = ${k}) = ${choose(n,k)}/${2**n} = ${pct(vals[k])}</div><p>All PMF probabilities add to 1. ${k===0?'Zero heads means all tails.':k===n?'All heads is only one sequence.':'Middle counts can occur in more ways than extremes.'}</p>`);miniStats($('.sim-stats',s),[['Experiments',runs],['Individual tosses',runs*n],['Observed X = '+k,runs?pct((counts[k]||0)/runs):'—']])}button($('.simulation .button-row',s),'Repeat 500 experiments',()=>{if(!counts.length)counts=Array(n+1).fill(0);for(let j=0;j<500;j++){let heads=0;for(let i=0;i<n;i++)heads+=Math.random()<.5?1:0;counts[heads]++;runs++}refresh();mark()},'primary');button($('.simulation .button-row',s),'Reset samples',()=>{runs=0;counts=[];refresh()});refresh()}draw()}
function combinations(){problem('Choose two head positions','Five coin tosses have five labelled positions. To get exactly two heads, choose which two positions are H; the remaining three are T. Does selecting position 2 then 4 differ from selecting 4 then 2?');const r=$('#activity');let picked=new Set(),found=new Set();r.innerHTML='<p>Select exactly two positions, then save the arrangement.</p><div class="positions"></div><div class="button-row"></div><div class="combo-feedback" aria-live="polite"></div><div class="found-combos"></div><div class="combo-answer"></div><details class="factorial"><summary>Why divide by the orderings?</summary><p>Choosing a first position and a second gives 5×4 = 20 ordered choices. Every pair is counted twice: (2,4) and (4,2). Divide by 2! = 2 to get 10 distinct pairs.</p><p>More generally, C(n,k) = n!/[k!(n−k)!]. Choosing heads or choosing tails specifies the same sequence, so C(n,k)=C(n,n−k).</p><div class="factorial-exercise"></div></details>';for(let i=0;i<5;i++){let b=button($('.positions',r),'T',()=>{picked.has(i)?picked.delete(i):picked.add(i);b.textContent=picked.has(i)?'H':'T';b.classList.toggle('selected');b.setAttribute('aria-pressed',picked.has(i))},'position');b.setAttribute('aria-label','Toss position '+(i+1));b.setAttribute('aria-pressed','false')}button($('.button-row',r),'Save this arrangement',()=>{if(picked.size!==2){$('.combo-feedback',r).textContent='Choose exactly two H positions.';return}let seq=Array.from({length:5},(_,i)=>picked.has(i)?'H':'T').join('');let old=found.has(seq);found.add(seq);$('.combo-feedback',r).textContent=old?'You already found this pair. Reversing the selection order does not create a new arrangement.':`Saved. ${found.size} distinct arrangements found.`;$('.found-combos',r).innerHTML='<div class="sequence-list">'+[...found].map(v=>`<code>${v}</code>`).join('')+'</div>';mark()},'primary');button($('.button-row',r),'Reveal all arrangements',()=>{found=new Set(coins(5).filter(v=>v.split('H').length-1===2));$('.found-combos',r).innerHTML='<div class="sequence-list">'+[...found].map(v=>`<code>${v}</code>`).join('')+'</div>';$('.combo-feedback',r).textContent='All 10 arrangements are shown.';mark()});question($('.combo-answer',r),'How many distinct arrangements are possible?',10,'<div class="formula">C(5,2) = 5! / (2!3!) = 120 / (2×6) = 10</div><p>Each of the 10 sequences has probability 1/32 with fair independent tosses, giving 10/32 = 31.25%.</p>','arrangements');selector($('.factorial-exercise',r),'Arrange distinct objects in a row',['4 labelled objects','5 labelled objects'],v=>fact(v));function fact(v){let el=$('.factorial-answer',r);if(el)el.remove();el=document.createElement('div');el.className='factorial-answer';$('.factorial',r).append(el);let n=v?5:4;question(el,`How many orders for ${n} distinct objects?`,n===4?24:120,`<p>There are ${n} choices for the first place, ${n-1} for the next, and so on: ${n}! = ${n===4?'4×3×2×1 = 24':'5×4×3×2×1 = 120'}. Also, 0! = 1, so choosing no positions is exactly one empty choice.</p>`,'orders')}fact(0)}
function binomial(){const r=$('#activity');let n=5,p=.5,k=2;const presets=[['5 fair tosses · exactly 2 heads',5,.5,2],['5 biased tosses · p(heads) = 0.3',5,.3,2],['5 die rolls · exactly 3 ones',5,1/6,3],['10 die rolls · count ones',10,1/6,2],['10 fair tosses · exactly 3 heads',10,.5,3]];const c=document.createElement('div'),s=document.createElement('div');r.append(c,s);selector(c,'Choose a model preset',presets.map(v=>v[0]),v=>{[,n,p,k]=presets[v];controls();draw()});c.insertAdjacentHTML('beforeend','<div id="bin-controls"></div>');function controls(){const el=$('#bin-controls');el.innerHTML='';slider(el,'Number of independent trials n',1,30,1,n,v=>{n=v;k=Math.min(n,k);const kr=$$('input',el)[2];kr.max=n;kr.value=k;kr.previousElementSibling.textContent=fmt(k);draw()});slider(el,'Success chance p',0,1,'any',p,v=>{p=v;draw()});slider(el,'Successes counted k',0,n,1,k,v=>{k=v;draw()})}function draw(){problem('Any arrangement with exactly k successes',`The current model has n = ${n} independent trials, constant success chance p = ${Math.abs(p-1/6)<1e-12?'1/6 (a die showing 1)':fmt(p,3)}, and asks for exactly k = ${k} successes. Preset changes are explicit; adjusting a slider creates a new model.`);let vals=Array.from({length:n+1},(_,i)=>binom(n,p,i));s.innerHTML=bars(vals,vals.map((_,i)=>i),k)+`<p class="hint">Horizontal: number of successes k · Vertical: probability. Parameters: n = ${n}, p = ${fmt(p,6)}.</p>`;question(s,`What is the chance of exactly ${k} successes?`,100*vals[k],`<div class="formula">C(${n},${k}) × ${fmt(p,6)}<sup>${k}</sup> × ${fmt(1-p,6)}<sup>${n-k}</sup><br>= ${choose(n,k)} × p<sup>${k}</sup> × (1−p)<sup>${n-k}</sup> = ${pct(vals[k])}</div><p>The coefficient counts arrangements. p<sup>k</sup>(1−p)<sup>n−k</sup> is the probability of one such arrangement. ${p===.3&&n===5?'For k=0,…,5, the masses are 0.16807, 0.36015, 0.3087, 0.1323, 0.02835, 0.00243.':''}</p>`)}controls();draw()}
function bernoulli(){const r=$('#activity');let mode=0;const c=document.createElement('div'),s=document.createElement('div');r.append(c,s);selector(c,'Define success for one trial',['Coin · heads is success','Die · face 1 is success','Fictional patient model · affected is success'],v=>{mode=v;draw()});function draw(){problem('Map one result to 0 or 1',mode===0?'For one fair toss, define X=1 for H and X=0 for T.':mode===1?'Roll one fair die. Define X=1 when the face is 1, and X=0 for any other face. The physical die has six outcomes, but this variable has only two values.':'In the same fictional rare-condition model, define X=1 for affected and X=0 for unaffected. The prior chance p is 1/10,000. “Success” is a counting label, not a favourable judgement.');const vals=mode===0?['H','T']:mode===1?[1,2,3,4,5,6]:['Affected','Unaffected'],p=mode===0?.5:mode===1?1/6:.0001;s.innerHTML='<p>Tap an observed result to apply the rule.</p><div class="bernoulli-choices button-row"></div><div class="bernoulli-result" aria-live="polite"></div>';vals.forEach((v,i)=>button($('.bernoulli-choices',s),''+v,()=>{$('.bernoulli-result',s).innerHTML=`<div class="formula">Observed ${v} → X = ${i===0?1:0}</div><p>P(X = 1) = ${pct(p)} · P(X = 0) = ${pct(1-p)}</p>`;mark()}));question(s,'What is P(X = 0), as a percentage?',100*(1-p),`<p>A Bernoulli PMF has P(X=1)=p and P(X=0)=1−p. Here 1−p = ${pct(1-p)}. One trial is Bernoulli; a sum of n independent trials with this same p is Binomial(n,p).</p>`)}draw()}
function continuous(){problem('From recorded times to a density','A support queue has waits from 0 to 5 minutes. Use an illustrative nonuniform model: a triangular density peaking at 1.4 minutes, with half the probability below 2 minutes. This same model is reused in the density and CDF experiments.');const r=$('#activity');let width=1;const c=document.createElement('div'),s=document.createElement('div');r.append(c,s);selector(c,'Width of each time bin',['1 minute','0.5 minute','0.25 minute','0.1 minute'],v=>{width=[1,.5,.25,.1][v];draw()});function draw(){const n=Math.round(5/width),probs=Array.from({length:n},(_,i)=>densityCDF((i+1)*width)-densityCDF(i*width)),heights=probs.map(v=>v/width);let max=.46,W=650,H=240,L=50,B=40,T=15,R=20,sx=x=>L+x/5*(W-L-R),sy=y=>H-B-y/max*(H-B-T);s.innerHTML=`<svg viewBox="0 0 ${W} ${H}" class="plot" role="img" aria-label="Density histogram using bins of width ${width} minutes"><title>Nonuniform waiting-time model; bin areas sum to 1</title>${heights.map((v,i)=>`<rect x="${sx(i*width)+1}" y="${sy(v)}" width="${(W-L-R)/n-2}" height="${H-B-sy(v)}" fill="#b7e2d5" stroke="#007f73"/>`).join('')}<path d="${Array.from({length:251},(_,i)=>`${i?'L':'M'}${sx(i/50)},${sy(density(i/50))}`).join(' ')}" fill="none" stroke="#007f73" stroke-width="3"/>${[0,1,2,3,4,5].map(i=>`<text x="${sx(i)}" y="${H-12}" text-anchor="middle">${i}</text>`).join('')}${[0,.2,.4].map(v=>`<text x="${L-7}" y="${sy(v)+4}" text-anchor="end">${v}</text>`).join('')}</svg><div class="plot-caption">Horizontal: wait in minutes · Vertical: density per minute</div><div class="formula">Bin height = probability in bin / bin width<br>Total area = Σ(height × width) = 1</div><p>The first bin [0, ${width}] has probability ${pct(probs[0])}, width ${width} min and height ${fmt(heights[0])} per minute. Narrower bins better trace the density; their heights do not need to sum to 1.</p>`;choiceQuestion(s,'Waits of 1.01 and 2.43 minutes are rounded for display. Is the underlying waiting-time model discrete?',['No, it still fills an interval','Yes, rounding changes the underlying model'],0,'The recorded rounded value is discrete, but the modelled actual wait is continuous. Binning is a way of displaying it.');}draw()}
function densityLab(){const r=$('#activity');let model=0,lo=2,hi=3;const c=document.createElement('div'),s=document.createElement('div');r.append(c,s);selector(c,'Two different call models',['Uniform queue · 0 to 5 min','Nonuniform triangular queue · 0 to 5 min'],v=>{model=v;draw()});const ranges=document.createElement('div');c.append(ranges);const low=slider(ranges,'Window begins (minutes)',0,5,.01,lo,v=>{lo=v;if(hi<lo){hi=lo;high.value=hi;high.previousElementSibling.textContent=fmt(hi)}draw()}),high=slider(ranges,'Window ends (minutes)',0,5,.01,hi,v=>{hi=v;if(lo>hi){lo=hi;low.value=lo;low.previousElementSibling.textContent=fmt(lo)}draw()});const presets=document.createElement('div');presets.className='button-row';c.append(presets);[[2,3],[2,2.5],[2,2],[1,2],[1,1.5]].forEach(([a,b])=>button(presets,`${a}–${b} min`,()=>{lo=a;hi=b;low.value=a;high.value=b;low.previousElementSibling.textContent=fmt(a);high.previousElementSibling.textContent=fmt(b);draw()}));function draw(){problem('How likely is this waiting window?',model?'Use the same nonuniform triangular queue as the previous experiment, supported on 0–5 minutes and peaking at 1.4 minutes. Equal-width intervals can now have different probabilities.':'This separate uniform support queue answers between 0 and 5 minutes. The density is 1/5 = 0.2 per minute throughout the interval.');const f=model?density:x=>x>=0&&x<=5?.2:0,F=model?densityCDF:x=>clamp(x/5,0,1),prob=F(hi)-F(lo);s.innerHTML=plot(f,{min:0,max:5,shadeMin:lo,shadeMax:hi,label:'Selected probability area under the waiting-time density'})+`<div class="plot-caption">Shaded window: ${fmt(lo)} to ${fmt(hi)} minutes · Vertical: density per minute</div>`;question(s,'What percentage of probability is shaded?',100*prob,model?`<p>The probability is the area from ${fmt(lo)} to ${fmt(hi)}: F(${fmt(hi)}) − F(${fmt(lo)}) = ${pct(prob)}. Narrowing an interval reduces its area; the exact point [2,2] has width zero and probability zero.</p><p>For this explicitly chosen model, f(t)=2t/7 for 0≤t≤1.4 and f(t)=(5−t)/9 for 1.4<t≤5, with 0 outside.</p>`:`<div class="formula">Width × height = (${fmt(hi)}−${fmt(lo)}) × 0.2 = ${pct(prob)}</div><p>${lo===hi?'The interval has zero width. Its probability is zero even though the density there is 0.2 per minute.':'Closed or open endpoints give the same area in this continuous model.'}</p>`)}draw()}
function stepCDFChart(n,x){const W=650,H=240,L=45,R=20,T=20,B=40,min=-1,max=Math.max(n+1,x),sx=v=>L+(v-min)/(max-min)*(W-L-R),sy=v=>H-B-v*(H-T-B);let d=`M${sx(-1)},${sy(0)}`,cum=0;for(let k=0;k<=n;k++){d+=` H${sx(k)} V${sy(cum+binom(n,.5,k))}`;cum+=binom(n,.5,k)}d+=` H${sx(n+1)}`;let y=Array.from({length:n+1},(_,i)=>i<=x?binom(n,.5,i):0).reduce((a,b)=>a+b,0);return `<svg class="plot" viewBox="0 0 ${W} ${H}" role="img" aria-label="Right-continuous step CDF for ${n} fair coin tosses; F(${x}) = ${y}"><title>Discrete CDF: P(X ≤ x)</title><path d="${d}" fill="none" stroke="#007f73" stroke-width="3"/><line x1="${sx(x)}" y1="${H-B}" x2="${sx(x)}" y2="${sy(y)}" stroke="#bd840d" stroke-dasharray="4 4"/><circle cx="${sx(x)}" cy="${sy(y)}" r="5" fill="#bd840d"/>${Array.from({length:Math.ceil(max)+2},(_,i)=>i-1).map(v=>`<text x="${sx(v)}" y="${H-12}" text-anchor="middle">${v}</text>`).join('')}${[0,.5,1].map(v=>`<text x="${L-8}" y="${sy(v)+4}" text-anchor="end">${v}</text>`).join('')}</svg>`}
function cdfLab(){const r=$('#activity');let mode=0,x=2;const c=document.createElement('div'),s=document.createElement('div');r.append(c,s);selector(c,'Choose the random variable',['Three-coin count · discrete','Uniform queue · 0–5 min','Nonuniform triangular queue · 0–5 min'],v=>{mode=v;draw()});slider(c,'Cutoff x',-1,6,.1,x,v=>{x=v;draw()});function draw(){problem('What is the chance of at most x?',mode===0?'Toss three fair independent coins and count heads. Add the probabilities at every count less than or equal to the cutoff. The probability at the cutoff is included.':`Use the ${mode===1?'uniform':'same triangular'} queue on 0–5 minutes. Collect all the density area to the left of x. At x=5, all the probability has been collected.`);const F=mode===0?t=>Array.from({length:4},(_,i)=>i<=t?binom(3,.5,i):0).reduce((a,b)=>a+b,0):mode===1?t=>clamp(t/5,0,1):densityCDF;s.innerHTML=`<h3>${mode===0?'Probability mass':'Probability density'}</h3>${mode===0?bars([1/8,3/8,3/8,1/8],['0','1','2','3']):plot(mode===1?t=>t>=0&&t<=5?.2:0:density,{min:-1,max:6,shadeMin:-1,shadeMax:x,label:'Probability accumulated through cutoff x'})}<h3>Cumulative probability F(x)</h3>${mode===0?stepCDFChart(3,x):plot(F,{min:-1,max:6,cdf:true,shadeMin:0,shadeMax:0,label:'Cumulative probability F(x)'})}<div class="plot-caption">Cutoff x = ${fmt(x)}. The CDF height is the probability collected so far.</div>`;question(s,`What is P(X ≤ ${fmt(x)})?`,100*F(x),`<div class="formula">F(${fmt(x)}) = ${pct(F(x))}</div><p>${mode===0?'Add the masses for 0,1,2,3 only when their values are ≤ the cutoff. Each jump belongs to its starting point: for example F(2)=7/8, while just below 2 it is 4/8.':'CDF height equals accumulated PDF area. '+(mode===2?'This model has F(2)=50%.':'In the uniform 0–5 model F(2)=40%.')}</p><p>A CDF is nondecreasing and right-continuous. It may have plateaus; it need not be smooth.</p>`)}draw()}
function uniform(){const r=$('#activity');let mode=0,a=0,b=10,lo=2,hi=3,runs=0;const presets=[['City bus · wait 0–10 minutes',0,10,2,3],['Uniform support queue · 0–15 minutes',0,15,2,3],['Uniform support queue · 0–5 minutes',0,5,2,3],['Unit interval · U(0,1)',0,1,.2,.5],['Abstract X · U(−2,3), window −1 to 3',-2,3,-1,3],['Abstract X · U(−2,3), window −1 to 4',-2,3,-1,4],['Abstract X · U(−2,4)',-2,4,-1,3]];const c=document.createElement('div'),s=document.createElement('div');r.append(c,s);selector(c,'Choose a named model',presets.map(v=>v[0]),v=>{mode=v;[,a,b,lo,hi]=presets[v];runs=0;draw()});function draw(){problem('How much of the interval is covered?',mode===0?'Assume a bus departs exactly every 10 minutes and you arrive independently at a uniformly random point in its cycle. Then the wait is Uniform(0,10). This is a mathematical bus model.':mode<3?`This explicitly different support queue has a uniform answer wait between ${a} and ${b} minutes. The endpoint ${b} belongs to this chosen model.`:`X is an abstract measurement on [${a},${b}], so negative values are allowed. It is not a negative waiting time.`);const F=x=>clamp((x-a)/(b-a),0,1),prob=F(hi)-F(lo),min=Math.min(a,lo)-1,max=Math.max(b,hi)+1;s.innerHTML=`<div class="uniform-sliders"></div><div class="uniform-chart"></div><div class="uniform-quiz"></div><details class="simulation"><summary>Sample this uniform model</summary><div class="button-row"></div><div class="uniform-samples"></div></details><details><summary>Adjust the support itself</summary><p>A new interval makes a new abstract model. A must stay below B.</p><div class="support-controls"><label>Start a<input id="support-a" type="number" step="any" value="${a}"></label><label>End b<input id="support-b" type="number" step="any" value="${b}"></label><button class="secondary" id="apply-support">Apply interval</button></div><p id="support-error" aria-live="polite"></p></details>`;const controls=$('.uniform-sliders',s);let start=slider(controls,'Window begins',min,max,'any',lo,v=>{lo=v;if(hi<lo){hi=lo;end.value=hi;end.previousElementSibling.textContent=fmt(hi)}update()}),end=slider(controls,'Window ends',min,max,'any',hi,v=>{hi=v;if(lo>hi){lo=hi;start.value=lo;start.previousElementSibling.textContent=fmt(lo)}update()});function update(){const p=F(hi)-F(lo);$('.uniform-chart',s).innerHTML=plot(x=>x>=a&&x<=b?1/(b-a):0,{min,max,shadeMin:lo,shadeMax:hi,label:'Uniform density and selected window'})+`<div class="formula">Support [${fmt(a)}, ${fmt(b)}] · Density = 1/${fmt(b-a)} = ${fmt(1/(b-a),6)}</div><p>Window: [${fmt(lo)}, ${fmt(hi)}]. Only its overlap with [${a}, ${b}] contributes area.</p>`;$('.uniform-quiz',s).innerHTML='';question($('.uniform-quiz',s),'What percentage lies in the window?',100*p,`<div class="formula">Overlap length / support length = ${fmt(Math.max(0,Math.min(hi,b)-Math.max(lo,a)))}/${fmt(b-a)} = ${pct(p)}</div><p>F(x)=0 below a; (x−a)/(b−a) inside; 1 at and above b. ${a===-2&&b===3?'Both windows (−1,3) and (−1,4) have probability 4/5 = 80%. No values occur beyond 3.':''} ${b-a<1?'A density above 1 is allowed: its total area, not its height, must equal 1.':''}</p>`)}let counts=Array(10).fill(0);button($('.simulation .button-row',s),'Draw 200 samples',()=>{for(let i=0;i<200;i++)counts[Math.floor(Math.random()*10)]++;runs+=200;$('.uniform-samples',s).innerHTML=bars(counts.map(v=>v/runs),counts.map((_,i)=>fmt(a+(i+.5)*(b-a)/10,1)))+`<p>${runs} observations. Each equal-width bin has model probability 10%; actual frequencies fluctuate.</p>`;mark()},'primary');button($('.simulation .button-row',s),'Reset samples',()=>{counts=Array(10).fill(0);runs=0;$('.uniform-samples',s).innerHTML=''});$('#apply-support').onclick=()=>{let av=$('#support-a').value,bv=$('#support-b').value,aa=+av,bb=+bv;if(!av.trim()||!bv.trim()||!Number.isFinite(aa)||!Number.isFinite(bb)||aa>=bb||bb-aa<.01||Math.abs(aa)>10000||Math.abs(bb)>10000){$('#support-error').textContent='Use finite endpoints between −10,000 and 10,000, with a width of at least 0.01.';return}a=aa;b=bb;lo=a;hi=b;mode=7;runs=0;draw()};update()}draw()}
function normalLab(){const r=$('#activity');let mu=2,sigma=3,x=2;const c=document.createElement('div'),s=document.createElement('div');r.append(c,s);selector(c,'Choose a normal model',['Curve-fitting example · μ=2, σ=3','Standard normal · μ=0, σ=1','Standardisation example · μ=2, σ=2.5'],v=>{[mu,sigma]=[[2,3],[0,1],[2,2.5]][v];x=mu;controls();draw()});c.insertAdjacentHTML('beforeend','<div id="normal-controls"></div>');function controls(){const el=$('#normal-controls');el.innerHTML='';slider(el,'Centre μ',-5,5,.1,mu,v=>{mu=v;draw()});slider(el,'Spread σ',.25,5,.05,sigma,v=>{sigma=v;draw()});slider(el,'Cutoff x',-15,15,.1,x,v=>{x=v;draw()})}function draw(){problem('Where does the bell place probability?',`The current normal model is N(${fmt(mu)}, ${fmt(sigma*sigma)}): centre μ = ${fmt(mu)} and standard deviation σ = ${fmt(sigma)}. Predict the chance of a value at most x = ${fmt(x)}.`);const min=Math.min(mu-4*sigma,x-1),max=Math.max(mu+4*sigma,x+1),F=t=>Phi((t-mu)/sigma);s.innerHTML=plot(t=>phi((t-mu)/sigma)/sigma,{min,max,shadeMin:min,shadeMax:x,label:'Normal density; shaded area to cutoff x'})+`<div class="plot-caption">The density continues beyond the displayed range in both directions.</div><div class="formula">f(x) = exp[−(x−μ)²/(2σ²)] / [σ√(2π)]</div><h3>The corresponding CDF</h3>`+plot(F,{min,max,cdf:true,shadeMin:0,shadeMax:0,label:'Normal cumulative distribution'})+'<div class="normal-answer"></div>';question($('.normal-answer',s),'What is P(X ≤ x)?',100*F(x),`<p>Convert the cutoff to z = (${fmt(x)}−${fmt(mu)})/${fmt(sigma)} = ${fmt((x-mu)/sigma)}. The standard normal CDF gives approximately <b>${pct(F(x))}</b>.</p><p>The centre divides probability in half. Increasing σ spreads the curve and lowers its peak while total area stays 1. The CDF is evaluated numerically.</p>`)}controls();draw()}
function standard(){problem('Measure distance in standard deviations','Keep the fixed normal model X ∼ N(2,2.5²). If x = 7, it is 5 units above the mean. How many standard deviations is that? Move x and watch the same event on the original and standard scales.');const r=$('#activity');let x=7;const c=document.createElement('div'),s=document.createElement('div');r.append(c,s);slider(c,'Original cutoff x',-8,12,.1,x,v=>{x=v;draw()});function draw(){const z=(x-2)/2.5;s.innerHTML=`<div class="standard-steps"><div><small>ORIGINAL VALUE</small><strong>${fmt(x)}</strong></div><span>− 2 →</span><div><small>DISTANCE FROM MEAN</small><strong>${fmt(x-2)}</strong></div><span>÷ 2.5 →</span><div><small>STANDARD SCORE z</small><strong>?</strong></div></div><h3>X ∼ N(2, 6.25)</h3>${plot(v=>phi((v-2)/2.5)/2.5,{min:-8,max:12,shadeMin:-8,shadeMax:x,label:'Original normal scale'})}<h3>Z ∼ N(0, 1)</h3>${plot(phi,{min:-4,max:4,shadeMin:-4,shadeMax:z,label:'Standard normal scale with the same probability shaded'})}`;question(s,'What is the standard score z?',z,`<div class="formula">z = (x−μ)/σ = (${fmt(x)}−2)/2.5 = ${fmt(z)}</div><p>The cutoff is ${fmt(Math.abs(z))} standard deviations ${z<0?'below':'above'} the mean. P(X ≤ ${fmt(x)}) = P(Z ≤ ${fmt(z)}) ≈ ${pct(Phi(z))}. The numerical scale changes; the shaded probability does not.</p>`,'standard deviations',.025)}draw()}
function gammaHalf(x){if(Number.isInteger(x)){let g=1;for(let i=1;i<x;i++)g*=i;return g}let g=Math.sqrt(Math.PI);for(let v=.5;v<x;v++)g*=v;return g}
function chiPDF(w,k){if(w<0)return 0;if(w===0)return k===1?Infinity:k===2?.5:0;return w**(k/2-1)*Math.exp(-w/2)/(2**(k/2)*gammaHalf(k/2))}
function chiCDF(w,k){if(w<=0)return 0;let df=k%2?1:2,v=df===1?2*Phi(Math.sqrt(w))-1:1-Math.exp(-w/2);for(;df<k;df+=2)v-=(w/2)**(df/2)*Math.exp(-w/2)/gammaHalf(df/2+1);return clamp(v,0,1)}
function chi(){problem('From signal noise to noise power','Imagine transmitting the bits 10010. Model the noise on each transmission by an independent Z ∼ N(0,1). Noise can be positive or negative. Its squared value is a nonnegative measure of power.');const r=$('#activity');let k=1,w=1;const c=document.createElement('div'),s=document.createElement('div');r.append(c,s);selector(c,'Independent noise terms to square and add',['1 term · χ² with 1 degree of freedom','2 terms · χ² with 2 degrees of freedom','5 terms · χ² with 5 degrees of freedom'],v=>{k=[1,2,5][v];draw()});slider(c,'Power cutoff w',0,20,.1,w,v=>{w=v;draw()});function draw(){s.innerHTML=`<div class="formula">W = ${Array.from({length:k},(_,i)=>`Z${['₁','₂','₃','₄','₅'][i]}²`).join(' + ')} ≥ 0</div><div class="button-row"></div><div class="noise-sample" aria-live="polite"></div><h3>Chi-square CDF</h3>${plot(v=>chiCDF(v,k),{min:0,max:20,cdf:true,shadeMin:0,shadeMax:0,label:`Chi-square cumulative probability, ${k} degrees of freedom`})}<p>Cutoff w = ${fmt(w)}. ${k===1?'For one square, W ≤ w is exactly the same event as −√w ≤ Z ≤ √w.':'Every additional independent squared standard-normal term contributes to the total power.'}</p>${k===1?plot(phi,{min:-4,max:4,shadeMin:-Math.sqrt(w),shadeMax:Math.sqrt(w),label:'Equivalent interval under the standard normal density'}):''}<div class="chi-answer"></div>`;button($('.button-row',s),'Sample noise and square it',()=>{const z=Array.from({length:k},normalSample),power=z.reduce((a,b)=>a+b*b,0);$('.noise-sample',s).innerHTML=`<p>Noise values: ${z.map(v=>fmt(v,3)).join(', ')}</p><div class="formula">Squared sum W = ${fmt(power,3)}</div>`;mark()},'primary');question($('.chi-answer',s),`What is P(W ≤ ${fmt(w)})?`,100*chiCDF(w,k),k===1?`<div class="formula">F<sub>W</sub>(w) = Φ(√w) − Φ(−√w)<br>= Φ(${fmt(Math.sqrt(w))}) − Φ(${fmt(-Math.sqrt(w))}) ≈ ${pct(chiCDF(w,1))}</div><p>Both +√w and −√w square to w. Folding these two sides together explains the nonnegative distribution. F(w)=0 for negative w.</p>`:`<p>For k=${k} independent squared standard-normal terms, the chi-square CDF at ${fmt(w)} is approximately ${pct(chiCDF(w,k))}. The degrees of freedom count the independent terms being squared, not the possible outcomes.</p>`)}draw()}
function inversePhi(u){let a=-9,b=9;for(let i=0;i<70;i++){let m=(a+b)/2;if(Phi(m)<u)a=m;else b=m}return (a+b)/2}
function sampling(){problem('Make a random number follow a chosen distribution','A uniform random number gives equal probability to equal-length pieces of [0,1). Give green 30% of the interval, blue 50%, and orange 20%. Then use the same principle to sample a normal distribution.');const r=$('#activity');let mode=0,u=.5;const c=document.createElement('div'),s=document.createElement('div');r.append(c,s);selector(c,'Sampling method',['Three colours · partition the unit interval','Standard normal · invert the CDF'],v=>{mode=v;draw()});slider(c,'Choose a uniform value u',.001,.999,.001,u,v=>{u=v;draw()});function draw(){const color=u<.3?'Green':u<.8?'Blue':'Orange',x=inversePhi(u);s.innerHTML=mode===0?`<div class="sampling-strip"><span style="width:30%;background:#007f73">Green<br>30%</span><span style="width:50%;background:#2367be">Blue<br>50%</span><span style="width:20%;background:#bf591b">Orange<br>20%</span><i style="left:${u*100}%" aria-label="Selected uniform value"></i></div><div class="strip-ticks"><span>0</span><span>0.3</span><span>0.8</span><span>1</span></div><p>[0,0.3) → green; [0.3,0.8) → blue; [0.8,1) → orange. The intervals cover all possibilities without overlap.</p><div class="formula">u = ${fmt(u,3)} → ${color}</div>`:`<div class="inverse-plot"></div><div class="formula">u = ${fmt(u,3)} → x = Φ⁻¹(u) ≈ ${fmt(x,3)}</div><p>Start at height u on the CDF, move horizontally to the curve, then down to x. Uniform heights become normal-distributed values. Values exactly 0 and 1 would require infinite normal cutoffs, so this control stays strictly inside.</p>`;if(mode===1){const W=650,H=260,L=45,R=20,T=15,B=40,sx=v=>L+(v+4)/8*(W-L-R),sy=v=>H-B-v*(H-T-B);$('.inverse-plot',s).innerHTML=`<svg class="plot" viewBox="0 0 ${W} ${H}" role="img" aria-label="Inverse normal CDF: uniform height ${u} maps to ${x}"><path d="${Array.from({length:201},(_,i)=>{let v=-4+i/25;return `${i?'L':'M'}${sx(v)},${sy(Phi(v))}`}).join(' ')}" fill="none" stroke="#007f73" stroke-width="3"/><path d="M${L},${sy(u)} H${sx(x)} V${H-B}" stroke="#bd840d" fill="none" stroke-width="2" stroke-dasharray="5 4"/><circle cx="${sx(x)}" cy="${sy(u)}" r="5" fill="#bd840d"/>${[-4,-2,0,2,4].map(v=>`<text x="${sx(v)}" y="${H-12}" text-anchor="middle">${v}</text>`).join('')}${[0,.5,1].map(v=>`<text x="${L-8}" y="${sy(v)+4}" text-anchor="end">${v}</text>`).join('')}</svg>`}s.insertAdjacentHTML('beforeend','<div class="button-row"></div><div class="sample-results" aria-live="polite"></div>');button($('.button-row',s),'Draw 1,000 samples',()=>{if(!mode){let counts=[0,0,0];for(let i=0;i<1000;i++){let v=Math.random();counts[v<.3?0:v<.8?1:2]++}$('.sample-results',s).innerHTML=bars(counts.map(n=>n/1000),['Green','Blue','Orange'])+`<p>Observed counts: ${counts.join(', ')}. Model probabilities remain 30%, 50%, 20%.</p>`}else{let counts=Array(16).fill(0),outside=0;for(let i=0;i<1000;i++){let v=inversePhi(clamp(Math.random(),1e-10,1-1e-10)),bin=Math.floor((v+4)*2);if(bin>=0&&bin<16)counts[bin]++;else outside++}$('.sample-results',s).innerHTML=bars(counts.map(n=>n/1000),counts.map((_,i)=>fmt(-3.75+i*.5,2)))+`<p>1,000 inverse-CDF samples. Histogram bins have width 0.5. ${outside} samples fell outside the displayed range [−4,4].</p>`}mark()},'primary');choiceQuestion(s,mode?'Why are normal samples crowded near the centre?':'Why does blue occur most often? ',mode?['The CDF rises most steeply there','Uniform u values prefer 0.5']:['Blue gets the longest interval','The colour name changes the random generator'],0,mode?'A narrow x interval around the centre covers a large vertical probability range. u itself is uniform.':'The blue segment has length 0.5, so half of uniform draws land there in the long run.');}draw()}
function extra(title,body){const el=document.createElement('details');el.className='extra';el.innerHTML=`<summary>${title}</summary><div class="extra-body">${body}</div>`;$('#extras').append(el);return $('.extra-body',el)}
function addExtras(l){if(l.id==='complement'){const el=extra('One more check: a 75% event','<p>An event has probability 75%. Its complement must fill the rest of the whole.</p>');question(el,'What is its complement probability?',25,'<p>100% − 75% = 25%. An event and its complement always add to the full probability of 1.</p>')}
if(l.id==='overlap'){let el=extra('When the overlap has not been given','<p>Suppose P(rain)=80% and P(wind)=70%. What is P(rain or wind)?</p>');choiceQuestion(el,'Can those two numbers alone determine the answer?',['No, the overlap is missing','Yes, add them to get 150%'],0,'The overlap could be 50% to 70%, so the union could be 100% down to 80%. We need the chance of both rain and wind.');const visual=document.createElement('div');el.append(visual);slider(el,'Explore an assumed overlap (%)',50,70,1,60,v=>{visual.innerHTML=`<div class="formula">80% + 70% − ${v}% = ${150-v}%</div>`});visual.innerHTML='<div class="formula">80% + 70% − 60% = 90%</div>';choiceQuestion(el,'Likewise, 6 cricket + 5 badminton in a class of 10: without the “3 both”, is the union fixed?',['No, we need the shared membership','Yes, it must be 11 students'],0,'The union depends on how many students belong to both clubs. Adding 6+5 treats two memberships as two different students.')}
if(l.id==='independence'){const el=extra('Independent is different from disjoint','<p>Knowing the first fair toss was H does not change P(H on the second)=1/2. But on a single die, learning the result is 2 rules out 3.</p>');choiceQuestion(el,'Are “roll 2” and “roll 3” on the same die independent?',['No: one rules the other out','Yes: they are different outcomes'],0,'They are disjoint, but not independent. Their joint chance is 0, whereas multiplying their individual chances gives 1/36.');choiceQuestion(el,'Does knowing a chess move usually affect what moves are possible next?',['Yes, the next move depends on it','No, successive moves are independent'],0,'The new board position changes the possible next moves. Different moments do not automatically mean independence.')}
if(l.id==='conditional'){let el=extra('Everyday evidence: weather and Friday shopping','<p>Learning that yesterday was rainy may change your estimate of today’s humidity. No numerical humidity rates are specified, so the effect cannot be calculated here.</p><p>In a separate fictional shop, 60% of shoe buyers also buy socks. Among shoe buyers shopping on Friday, the rate is 80%.</p>');selector(el,'Evidence available',['Customer buys shoes','Customer buys shoes AND it is Friday'],v=>{$('.shop-result',el).innerHTML=`<div class="formula">P(socks | shoes${v?', Friday':''}) = ${v?'80':'60'}%</div>`});el.insertAdjacentHTML('beforeend','<div class="shop-result"><div class="formula">P(socks | shoes) = 60%</div></div>');choiceQuestion(el,'Does the 80% tell us P(Friday | bought socks)?',['No, that reverses the condition','Yes, all conditional probabilities reverse'],0,'Friday given socks needs additional counts or probabilities. The direction of “given” matters.')}
if(l.id==='naive'){const el=extra('Why the “naïve” assumption is only an approximation','<p>In real language, seeing “good” can make “morning” more likely. Clues need not be independent, even inside a class.</p><p>With 100 words, the exact word combination may never have appeared in a small training inbox. Direct counting can then give no usable denominator. The naïve model estimates a joint likelihood from individual word likelihoods.</p>');choiceQuestion(el,'What independence does this classifier assume?',['Words are independent given the class','Words are always independent in all emails'],0,'The multiplication is done separately within spam and within regular messages. It does not assert independence across the entire inbox.');const ml=extra('Where these ideas appear in machine learning','<p>A model can use evidence to estimate an uncertain label, or learn a distribution from which to generate an outcome. These cards describe concepts; they do not run real prediction models.</p><div class="ml-cards"></div>');const cases=[['Email','Words, recipients, attachments','Spam or regular','P(spam | email features)'],['Image','Image pixels','Cat or not cat','P(cat | pixels). A toy cat image might receive 90% cat, 10% not cat; a different car image might receive 10% cat. These are illustrative model scores.'],['Sentiment','The words “I am happy to see you”','Happy or sad tone','P(happy | words). No calibrated numerical score is specified.'],['Patient','Age 29; female; height 169 cm; weight 62 kg; non-smoker; heart rate 63; blood pressure 120/90; symptoms and history','Health status','A conditional prediction would need a defined, validated model. These example inputs alone supply no health probability.'],['Generated face','A learned distribution of face images','A new pixel arrangement','A generative model samples a plausible image from a learned distribution.'],['Generated text','Earlier words and topic','The next word or continuation','A text model can sample continuations from conditional word/token distributions.']];cases.forEach(([name,evidence,target,note])=>{const e=document.createElement('div');e.className='ml-card';e.innerHTML=`<h3>${name}</h3><p>Known: ${evidence}</p>`;$('.ml-cards',ml).append(e);choiceQuestion(e,'What is uncertain?',[target,'The already supplied evidence'],0,note)})}
if(l.id==='random'||l.id==='continuous'){const el=extra('Sort the other examples: discrete or continuous','<p>Classify the variable itself, not how a measuring device displays it.</p><div class="sorter"></div>');const cases=[['Number of ones in die rolls',0,'A whole-number count.'],['Number of affected patients in a group',0,'A count from 0 up to the group size.'],['Number of defective products in a shipment',0,'A count of products.'],['Number of children with a given age or height',0,'The property is measured, but this variable counts children.'],['Population of a town',0,'A whole-number count, even if it is large.'],['Toss number on which the first head occurs',0,'Possible values 1,2,3,… form an infinite but countable set. There is no fixed upper limit.'],['Temperature model',1,'Values can fall between other values; an idealised measurement is continuous.'],['Time until the next bus',1,'The idealised wait can take any value in an interval.'],['Height of a gymnast’s jump',1,'An idealised height can vary continuously.'],['Millimetres of rainfall in November',1,'A simplified positive-rainfall measurement is continuous. A full rainfall model can also put a probability mass at exactly zero.'],['The invented values 1, −7, 3.14159',0,'Only three possible values: discrete even though one has decimals.']];let pos=0;function show(){const c=cases[pos];$('.sorter',el).innerHTML=`<p><b>${pos+1}/${cases.length}: ${c[0]}</b></p><div class="sort-options"></div>`;choiceQuestion($('.sort-options',el),'Which type fits?',['Discrete','Continuous'],c[1],c[2]);button($('.sorter',el),'Next example →',()=>{pos=(pos+1)%cases.length;show()})}show()}
if(l.id==='cdf'){const el=extra('Can this graph be a CDF?','<p>Check the range, whether it decreases, its left/right limits, and whether each jump includes its new value.</p><div class="cdf-validity"></div>');const shapes=[['A curve that goes below zero',false,x=>x<0?0:x<1?-.2*x:x<2?-.2+1.2*(x-1):1,'Probabilities cannot be negative.'],['A right-continuous staircase from 0 to 1',true,x=>x<0?0:x<1?.3:x<2?.8:1,'A step CDF is valid for a discrete variable. Its jumps are point probabilities.'],['A curve that rises and then dips',false,x=>x<0?0:x<1?.8*x:x<2?.8-.4*(x-1):x<3?.4+.6*(x-2):1,'A cumulative probability cannot decrease as the cutoff moves right.'],['An increasing curve with a flat plateau',true,x=>x<0?0:x<1?.4*x:x<2?.4:x<3?.4+.6*(x-2):1,'A plateau is allowed: the corresponding interval adds no probability.'],['A curve that ends at 2',false,x=>clamp(x,0,2),'A CDF cannot exceed 1 and must approach 1 on the far right.']];let pos=0;function show(){let [title,valid,f,reason]=shapes[pos];$('.cdf-validity',el).innerHTML=`<h3>${pos+1}. ${title}</h3>${valid||pos!==0?plot(f,{min:-1,max:4,height:2.1,shadeMin:0,shadeMax:0,label:title}):'<div class="formula">Example values: F(−1)=0, F(1)=−0.2, F(2)=1</div>'}<div class="valid-question"></div>`;choiceQuestion($('.valid-question',el),'Is this a possible CDF?',['Yes','No'],valid?0:1,reason);button($('.cdf-validity',el),'Next graph →',()=>{pos=(pos+1)%shapes.length;show()})}show()}
if(l.id==='normal'){const el=extra('Watch a binomial become bell-shaped','<p>Keep independent fair tosses, p=1/2, and increase n. The exact count remains discrete. A smooth normal approximation uses μ=np and σ=√[np(1−p)].</p><div class="approx-controls"></div><div class="approx-chart"></div>');let n=2;slider($('.approx-controls',el),'Number of tosses n',2,100,1,n,v=>{n=v;draw()});function draw(){let vals=Array.from({length:n+1},(_,k)=>binom(n,.5,k)),mu=n/2,sd=Math.sqrt(n/4),W=700,H=255,L=42,R=18,T=20,B=40,min=-1,max=n+1,ymax=Math.max(...vals)*1.18,sx=x=>L+(x-min)/(max-min)*(W-L-R),sy=y=>H-B-y/ymax*(H-B-T);let k=Math.floor(mu),exact=vals[k],approx=Phi((k+.5-mu)/sd)-Phi((k-.5-mu)/sd);$('.approx-chart',el).innerHTML=`<svg class="plot" viewBox="0 0 ${W} ${H}" role="img" aria-label="Exact binomial masses and normal density for ${n} fair tosses">${vals.map((v,k)=>`<rect x="${sx(k-.4)}" y="${sy(v)}" width="${.8*(W-L-R)/(max-min)}" height="${H-B-sy(v)}" fill="#7cbda9"/>`).join('')}<path d="${Array.from({length:251},(_,i)=>{let x=min+(max-min)*i/250;return `${i?'L':'M'}${sx(x)},${sy(phi((x-mu)/sd)/sd)}`}).join(' ')}" fill="none" stroke="#bd840d" stroke-width="3"/>${[0,.25,.5,.75,1].map(t=>`<text x="${sx(n*t)}" y="${H-12}" text-anchor="middle">${fmt(n*t,1)}</text>`).join('')}</svg><p>Teal bars: exact PMF. Gold curve: normal density; use its <b>area over a width-one interval</b>, not just its height, to approximate a count.</p><div class="formula">P(X=${k}) exact: ${pct(exact)}<br>Normal area from ${k-.5} to ${k+.5}: ${pct(approx)}</div><p>Here np = n(1−p) = ${n/2}. A common rule of thumb asks for both to be at least 5; accuracy depends on the event. Increasing n alone is not enough when p is extremely close to 0 or 1.</p>`}draw();const fit=extra('Build the normal curve: shift, stretch, normalise','<p>Fit a bell with centre 2 and spread 3. Follow four mathematical steps; only the final curve is a probability density.</p><div class="fit-controls"></div><div class="fit-chart"></div>');selector($('.fit-controls',fit),'Construction step',['Start: exp(−x²/2)','Shift to 2: exp(−(x−2)²/2)','Stretch to σ=3: exp(−(x−2)²/18)','Normalise: divide by 3√(2π)'],v=>show(v));function show(v){const mu=v?2:0,sigma=v>=2?3:1,norm=v===3?sigma*Math.sqrt(2*Math.PI):1;$('.fit-chart',fit).innerHTML=plot(x=>Math.exp(-((x-mu)**2)/(2*sigma*sigma))/norm,{min:-10,max:14,shadeMin:0,shadeMax:0,label:'Normal curve construction step'})+`<p>Area over the whole real line: ${v===3?'1':fmt(sigma*Math.sqrt(2*Math.PI))}. ${v===3?'Now this is a valid probability density.':'The shape is a bell, but its area is not yet 1.'}</p>`}show(0);const applications=extra('Where normal models are useful','<p>Height, weight, IQ scores and communication-channel noise are common examples of quantities sometimes approximated with normal models. The fit must be checked in context; height and weight cannot literally take every negative real value.</p><p>Sums of many independent effects can become approximately normal under suitable conditions, such as independent identically distributed contributions with finite variance. A sum is not always exactly normal.</p>');choiceQuestion(applications,'Does every sum of independent quantities have an exact normal distribution?',['No','Yes'],0,'A central-limit result is an approximation under conditions. The distribution and sample size matter.')}
if(l.id==='chi'){const el=extra('What does the chi-square density look like?','<p>The area under the density is 1. A one-degree-of-freedom density rises without bound as w approaches zero from the right, yet the probability at the exact point 0 is still zero.</p><div class="chi-density-controls"></div><div class="chi-density-plot"></div>');selector($('.chi-density-controls',el),'Degrees of freedom',['1','2','5'],v=>show([1,2,5][v]));function show(k){$('.chi-density-plot',el).innerHTML=plot(w=>chiPDF(w,k),{min:.03,max:20,shadeMin:.03,shadeMax:.03,label:`Chi-square density for ${k} degrees of freedom`})+'<p>The plotted range begins at w=0.03 to keep the vertical scale finite. The density is zero for negative w.</p>'}show(1)}
if(l.id==='sampling'){const el=extra('The three-colour sampler as a discrete CDF','<p>Map green → 0, blue → 1, orange → 2. Then P(X=0)=0.3, P(X=1)=0.5, P(X=2)=0.2.</p><div class="formula">F(x) = 0 for x&lt;0<br>F(x) = 0.3 for 0≤x&lt;1<br>F(x) = 0.8 for 1≤x&lt;2<br>F(x) = 1 for x≥2</div>');question(el,'What is P(X ≤ 1)?',80,'<p>Add green and blue: 0.3+0.5 = 0.8. The jump at 1 includes X=1, so F(1)=80%.</p>')}
}
const widgets={outcomes,product,rooms,birthday:birthdayLab,shoes,bayes,spam,naive,boxes,random:randomVariable,discrete,combinations,binomial,bernoulli,continuous,density:densityLab,cdf:cdfLab,uniform,normal:normalLab,standard,chi,sampling};
const hash=location.hash.slice(1),start=lessons.findIndex(l=>l.id===hash);$('#progress').max=lessons.length;navigate(start<0?0:start,false);
if(document.modelContext?.registerTool){const life=new AbortController();const tools=[{name:'read_probability_lesson',title:'Read current probability lesson',description:'Return the current experiment and its foundational takeaway.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({id:lessons[active].id,title:lessons[active].title,problem:$('#problem').textContent,foundation:lessons[active].concept,takeaway:lessons[active].take})},{name:'navigate_probability_lesson',title:'Open a probability experiment',description:'Open a lesson in the same interface by its exact lesson ID.',inputSchema:{type:'object',properties:{lesson_id:{type:'string',enum:lessons.map(l=>l.id)}},required:['lesson_id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||typeof input.lesson_id!=='string')throw new Error('A lesson_id is required');const i=lessons.findIndex(l=>l.id===input.lesson_id);if(i<0)throw new Error('Unknown lesson_id');navigate(i);return {id:lessons[i].id,title:lessons[i].title}}}];for(const t of tools){try{Promise.resolve(document.modelContext.registerTool(t,{signal:life.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>life.abort(),{once:true})}
